def is_checkerboard(grid):
    # Handle empty grid or single-cell grid
    if not grid or not grid[0]:
        return True

    rows, cols = len(grid), len(grid[0])
    # Determine the expected values for even and odd (row + col) sums
    expected_even = grid[0][0]
    expected_odd = grid[0][1] if cols > 1 else None

    if expected_odd is None and rows == 1 and cols == 1:
        return True

    # If there's only one row, check the pattern in that row
    if rows == 1:
        for col in range(1, cols):
            if (col + 0) % 2 == 0:
                if grid[0][col] != expected_even:
                    return False
            else:
                if grid[0][col] != expected_odd:
                    return False
        return True

    # If there's only one column, check the pattern in that column
    if cols == 1:
        for row in range(1, rows):
            if (row + 0) % 2 == 0:
                if grid[row][0] != expected_even:
                    return False
            else:
                if grid[row][0] != expected_odd:
                    return False
        return True

    # Check that the first two cells have different values
    if expected_odd is None or expected_odd == expected_even:
        return False

    # Check the rest of the grid
    for row in range(rows):
        for col in range(cols):
            if (row + col) % 2 == 0:
                if grid[row][col] != expected_even:
                    return False
            else:
                if grid[row][col] != expected_odd:
                    return False

    return True
```

