def parse_kv_pairs(s):
    """
    Parse a string of semicolon-separated key=value pairs into a dictionary.

    Args:
        s (str): Input string of the format "key1=value1;key2=value2;..."

    Returns:
        dict: Dictionary mapping keys to values (both as strings), with later values overwriting earlier ones.
    """
    if not s:
        return {}

    result = {}
    pairs = s.split(';')
    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)  # Split only on the first '='
            result[key] = value
    return result
```

