def parse_url_parts(url):
    # Split on '://' to separate scheme from the rest
    if '://' not in url:
        raise ValueError("URL must contain a scheme (e.g., 'http://')")

    scheme, rest = url.split('://', 1)

    # Split the rest into host, path, and query parts
    # First, find the index of the first '/' or '?'
    split_index = -1
    for i, char in enumerate(rest):
        if char in ('/', '?'):
            split_index = i
            break

    if split_index == -1:
        # No '/' or '?' found, so host is the entire rest
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:split_index]
        remainder = rest[split_index:]

        # Determine if it's a path or query
        if remainder.startswith('/'):
            # It's a path, find if there's a query
            path_end = remainder.find('?')
            if path_end == -1:
                path = remainder
                query = ''
            else:
                path = remainder[:path_end]
                query = remainder[path_end+1:]
        elif remainder.startswith('?'):
            path = ''
            query = remainder[1:]
        else:
            # This should not happen due to earlier check
            host = rest
            path = ''
            query = ''

    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query
    }
```

