def format_duration_minutes(minutes):
    if minutes == 0:
        return "0m"
    hours = minutes // 60
    remaining_minutes = minutes % 60

    parts = []
    if hours > 0:
        parts.append(f"{hours}h")
    if remaining_minutes > 0:
        parts.append(f"{remaining_minutes}m")

    return "".join(parts)
```

